/**
 * penguins.js
 * Entry point for the Penguin game.
 * Modularized for "MEGA EASY" extension and reading.
 */
import { PenguinManager } from './game/PenguinManager.js';
import { MapManager, WORLDS } from './game/MapManager.js';
import { GameConfig } from './game/GameConfig.js';

window.addEventListener('load', () => {
    // Initialize the game manager
    window.penguinManager = new PenguinManager();

    // Function to calculate igloo position
    window.calculateIglooPos = () => {
        const igloo = document.getElementById('igloo-img');
        const header = document.querySelector('#header .inner-header') || document.getElementById('header');

        let startX = 1290 / 2; // Default to header center
        let startY = 200;

        if (igloo && header) {
            const iRect = igloo.getBoundingClientRect();
            const hRect = header.getBoundingClientRect();

            // Calculate position relative to the inner relative container (stable across desktop centering and mobile horizontal scrolling)
            startX = (iRect.left - hRect.left) + 97 + (15 / 2);
            startY = (iRect.top - hRect.top) + 87 + (17 / 2);
        }
        return { x: startX, y: startY };
    };

    // Setup Igloo interactions
    const igloo = document.getElementById('igloo-img');
    const pos = window.calculateIglooPos();
    let startX = pos.x;
    let startY = pos.y;

    if (igloo) {
        igloo.style.cursor = 'pointer';
        igloo.addEventListener('click', () => {
            if (!window.penguinManager.hasJoined) {
                window.penguinManager.hasJoined = true;
                window.penguinManager.pendingSpawns += 1;
                window.penguinManager.ui.showUI();
                window.penguinManager.syncSceneryVisibility();

                // Broadcast takeover on spawning
                window.penguinManager.network.broadcastTakeover(window.penguinManager.myPenguinId);
                window.penguinManager.revealNameTags();
            } else {
                // Walk back to igloo if clicked while already out
                const player = window.penguinManager.penguins.find(p => p.isPlayer);
                if (player && !player.isEntering && !player.isLeaving) {
                    player.isLeaving = true;
                    player.autoMode = false;
                }
            }
        });
    }

    window.penguinManager.startX = startX;
    window.penguinManager.startY = startY;
});

// Console Helper: Set local penguin color and update server
window.setPenguinColor = (color) => {
    const manager = window.penguinManager;
    if (!manager) {
        console.error("PenguinManager not initialized yet.");
        return;
    }
    const player = manager.penguins.find(p => p.isPlayer);
    if (!player) {
        console.error("No active local penguin found.");
        return;
    }

    // Set the local color
    player.activeColor = color; // e.g. 'color_gray', 'color_pink', 'color_rainbow', or null
    console.log(`[CONSOLE] Setting local penguin color to: ${color}`);

    // Broadcast the change if connected
    if (manager.network && manager.network.socket) {
        const internalCenterX = 1290 / 2;
        const relativeFloorY = manager.getRelativeFloorY();
        manager.network.socket.emit('updatePenguin', {
            id: player.id,
            secret: manager.myPenguinSecret,
            x: player.x - internalCenterX,
            y: player.y - relativeFloorY,
            state: player.state,
            direction: player.direction,
            scale: player.scale,
            opacity: player.opacity,
            name: player.name,
            powerUpType: player.powerUpType,
            pancakeTimer: player.pancakeTimer,
            activeColor: color
        });
        console.log("[CONSOLE] Color update broadcasted to server.");
    } else {
        console.warn("[CONSOLE] Network not connected; color updated locally only.");
    }
};

// Console Helper: Add a test item directly into the player's inventory
window.addTestItem = (itemType) => {
    const manager = window.penguinManager;
    if (manager && manager.network) {
        manager.network.emitTestAddItem(itemType);
        console.log(`[CONSOLE] Requested test item "${itemType}" from server.`);
    } else {
        console.error("[CONSOLE] Network/PenguinManager not connected.");
    }
};

// Console Helper: Spawn a test ice cube locally (rendering + physics only;
// does NOT hit the server, so it won't persist or decrement inventory).
window.placeTestIceCube = (x, y) => {
    const manager = window.penguinManager;
    if (!manager || !manager.iceCubes) {
        console.error("[CONSOLE] IceCubeManager not initialized yet.");
        return;
    }
    const floorY = manager.getRelativeFloorY();
    const px = (x !== undefined) ? x : 400;
    const py = (y !== undefined) ? y : floorY - GameConfig.ICE_CUBE_SIZE;
    const player = manager.penguins.find(p => p.isPlayer);
    const id = "test_ice_" + Date.now() + "_" + Math.floor(Math.random() * 1000);
    manager.iceCubes.spawnIceCube({
        id: id,
        x: px - (1290 / 2),
        y: py - floorY,
        world: (player && player.currentWorld) || 'lobby',
        placedBy: manager.myPenguinId
    });
    console.log(`[CONSOLE] Spawned test ice cube ${id} at (${px}, ${py}).`);
    return id;
};

// Console Helper: Arm ice-cube placement mode (same as double-clicking the tray).
window.armIceCube = () => {
    const manager = window.penguinManager;
    const player = manager && manager.penguins.find(p => p.isPlayer);
    if (manager && manager.iceCubes && player) {
        manager.iceCubes.arm(player);
        console.log("[CONSOLE] Ice cube placement armed. Press E to place, ↑/↓ to nudge, Esc to cancel.");
    } else {
        console.error("[CONSOLE] IceCubeManager or local player not ready.");
    }
};


// Console Helper: Print your penguinId, useful for adding yourself to
// GameConfig.ADMIN_PENGUIN_IDS to unlock the admin teleport commands below.
window.whoami = () => {
    const manager = window.penguinManager;
    if (!manager) {
        console.error("PenguinManager not initialized yet.");
        return;
    }
    console.log(`penguinId: ${manager.myPenguinId} | name: ${manager.myPenguinName} | isAdmin: ${manager.isAdmin()}`);
    return manager.myPenguinId;
};

// Admin Console Command: List worlds currently playable (hardcoded WORLDS[...]
// entries plus any Level Editor maps saved server-side under data/maps/).
window.listWorlds = async () => {
    const manager = window.penguinManager;
    if (!manager || !manager.isAdmin()) {
        console.error("[ADMIN] Not authorized. Add your penguinId (see whoami()) to GameConfig.ADMIN_PENGUIN_IDS.");
        return;
    }
    console.log("Registered worlds:", Object.keys(WORLDS));
    const serverMaps = await MapManager.fetchServerMapList();
    console.log("Server-saved editor maps (data/maps/*.json):", serverMaps);
    return { registered: Object.keys(WORLDS), server: serverMaps };
};

// Admin Console Command: Teleport the local player into any world.
// - If `worldId` is already registered in WORLDS (e.g. 'lobby', 'caves', or a
//   previously loaded editor map), teleports instantly.
// - Otherwise, tries to fetch it live from the Level Editor's saved maps
//   (data/maps/<worldId>.json via page/editor_io.php) and registers it before
//   teleporting, so worlds built in the editor become playable without any
//   manual MapManager.js edits.
window.teleportTo = async (worldId, x = 100) => {
    const manager = window.penguinManager;
    if (!manager || !manager.isAdmin()) {
        console.error("[ADMIN] Not authorized. Add your penguinId (see whoami()) to GameConfig.ADMIN_PENGUIN_IDS.");
        return;
    }
    const player = manager.penguins.find(p => p.isPlayer);
    if (!player) {
        console.error("[ADMIN] No active local penguin found — join the game first.");
        return;
    }

    if (!WORLDS[worldId]) {
        console.log(`[ADMIN] "${worldId}" not registered yet, trying to load it from data/maps/${worldId}.json...`);
        const loaded = await MapManager.loadWorldFromServer(worldId);
        if (!loaded) {
            console.error(`[ADMIN] Could not load world "${worldId}". Use listWorlds() to see available names.`);
            return;
        }
        console.log(`[ADMIN] Registered "${worldId}" (${loaded.name}).`);
    }

    MapManager.transitionWorld(manager, player, worldId, x);
    console.log(`[ADMIN] Teleported to "${worldId}" at x=${x}.`);
};

/**
 * GameConfig.js
 * Centralized configuration for the Penguin game.
 * Easy for AI and humans to tweak the game physics and settings.
 */
export const GameConfig = {
    // Physics
    GRAVITY: 800,
    JUMP_FORCE: -350,
    WALK_SPEED: 150,
    SLIDE_SPEED: 250,

    // Water (gentle waves)
    WATER_GRAVITY: 260,      // reduced gravity while swimming
    WATER_MAX_FALL: 90,      // terminal sink speed while swimming
    SWIM_SPEED: 120,         // vertical swim speed (W up / S down)
    WATER_DRAG: 1.2,         // horizontal drag multiplier in water
    WATER_JUMP_FORCE: 260,        // upward launch strength of the small hop out of water
    WATER_OPACITY: 0.6,      // sprite opacity while swimming underwater (filter-independent)
    DROWN_DELAY: 0.4,        // (legacy) seconds at the bottom of shark water before respawn
    RESPAWN_DELAY: 1.5,      // seconds after dying before respawning at the igloo/spawn

    // Penguin Settings
    TARGET_SCALE: 1.25,
    START_SCALE: 0.5,
    COLLISION_RADIUS: 24,
    FISH_COLLISION_RADIUS: 32,

    // Animation
    DEFAULT_FPS: 10,
    IDLE_FPS: 3,
    SWIM_FPS: 10,
    SWIM_IDLE_FPS: 2,
    STATE_FRAMES: [2, 4, 1, 1, 3, 2, 2], // 0: Idle, 1: Walk, 2: Jump, 3: Hurt, 4: Slide, 5: Swim, 6: Swim Idle

    // Timing
    DOOR_PAUSE_TIME: 1.0,
    HURT_TIME: 0.3,
    AUTO_PILOT_IDLE_TIME: 120.0,
    NETWORK_UPDATE_INTERVAL: 50, // ms
    SERVER_TIMEOUT: 5000, // ms - time before server considers player disconnected
    MAX_FRAME_DT: 0.1,      // s - cap on per-frame delta time (prevents physics explosion on tab-out/lag)

    // Paths
    SPRITE_SHEET_PATH: '/img/Penguin SpriteSheet.png',

    // Offsets
    FLOOR_OFFSET: -45,
    // Water pools pin their floor (bottom edge) at this offset from the bottom
    // of the header. 0 = flush with the header's bottom edge.
    WATER_FLOOR_OFFSET: 0,

    // Rendering (z-index ordering of world scenery, lowest = drawn behind).
    // Platforms (incl. slopes), water and portals can each override the default
    // via an optional `zIndex` field set in the Level Editor.
    RENDER_Z: {
        PLATFORM: 1,
        WATER: 2,
        PORTAL: 4,
        ICE_HOLE: 5,
    },

    // Power-ups
    POWERUP_DURATION: 10.0,
    SPEED_MULTIPLIER: 2.0,
    GIANT_MULTIPLIER: 3.0,
    GIANT_SPEED_FACTOR: 0.5,
    GIANT_CRUSH_DELAY: 0.5,     // s of sustained contact before a giant crushes an ice cube
    GIANT_CRUSH_CONTACT_PX: 6,  // px contact tolerance (feet-on-top / side-push)

    // Ice Cubes (placeable physics blocks)
    ICE_CUBE_SIZE: 28,
    ICE_CUBE_LIFETIME: 7200,      // seconds (~2h) before a placed cube melts away
    ICE_CUBE_PLACE_OFFSET: 34,    // px in front of the penguin when placing
    ICE_CUBE_FLOOR_OFFSET: 8,     // px to lower the cube floor so cubes align with the penguin's visual feet
    ICE_CUBE_WATER_FLOAT: 10,     // px of a floating cube's top that stays above the water surface
    ICE_CUBE_SETTLE_RATE: 8,      // 1/s — how fast a displaced cube glides back to the float line
    ICE_CUBE_PACK_PRICE: 40,
    ICE_CUBE_PACK_QTY: 4,

    // Emotes
    EMOTE_MAP: {
        '1': '❤️',
        '2': '🐟',
        '3': '❄️',
        '4': '✨',
        '5': '🐧'
    },

    // Admin
    // Add your own penguinId (run `whoami()` in the browser console once
    // you've joined the game) to unlock admin console commands like
    // `teleportTo()` / `listWorlds()` (see js/penguins.js).
    ADMIN_PENGUIN_IDS: ['hqet3ipdt1'],

    // Viewport
    MOBILE_BREAKPOINT: 768,

    // Shop
    SHOP_X: 200,
    SHOP_Y: 81,
    SHOP_PROXIMITY: 100,
    SHOP_BUBBLE_OFFSET_X: 20,
    SHOP_BUBBLE_OFFSET_Y: 60,

    // Speech bubbles (penguin-anchored). Margin is the offset applied to every
    // bubble: X from the penguin's center, Y from the top of the penguin's head.
    SPEECH_BUBBLE_MARGIN_X: 5,
    SPEECH_BUBBLE_MARGIN_Y: 5,

    // Customization Offsets
    HAT_OFFSET_X: 2,
    HAT_OFFSET_Y_NORMAL: -5,
    HAT_OFFSET_Y_GIANT: -4,

    // Shop Items
    SHOP_ITEMS: {
        consumables: [
            { id: 'magnet', name: 'Magnet', price: 30, type: 'magnet', icon: '🧲', description: 'Used at the Ice Hole to salvage treasure!' },
            { id: 'ice_cube', name: 'Ice Cube Tray (4)', price: 40, type: 'ice_cube', icon: '🧊', description: 'Place physical ice cubes to build structures! (4 pack)' },
            { id: 'speed', name: 'Lightning Speed', price: 10, type: 'speed', icon: '⚡', description: 'Move faster for a while!' },
            { id: 'shield', name: 'Snow Shield', price: 15, type: 'shield', icon: '🛡️', description: 'Protect yourself from snowballs!' },
            { id: 'giant', name: 'Giant Potion', price: 25, type: 'giant', icon: '🐘', description: 'Become a giant for a while!' },
        ],
        clothing: [
            { id: 'red_hat', name: 'Red Hat', price: 50, type: 'hat_red', icon: '🎩', description: 'A stylish red hat.' },
            { id: 'glasses', name: 'Glasses', price: 75, type: 'glasses', icon: '👓', description: 'Cool hipster glasses.' }
        ],
        customization: [
            { id: 'color_gray', name: 'Silver Penguin', price: 100, type: 'color', icon: '🔘', description: 'Change your color to sleek silver gray!' },
            { id: 'color_pink', name: 'Pink Penguin', price: 500, type: 'color', icon: '💗', description: 'Change your color to pink!' },
            { id: 'color_rainbow', name: 'Rainbow Penguin', price: 10000, type: 'color', icon: '🌈', description: 'Become an ultra-rare rotating rainbow penguin!' }
        ]
    }
};

