1	/**
2	 * NetworkManager.js
3	 * Handles Socket.io and BroadcastChannel communication.
4	 */
5	import { RemotePenguin } from './RemotePenguin.js';
6	import { GameConfig } from './GameConfig.js';
7	
8	export class NetworkManager {
9	    constructor(manager) {
10	        this.manager = manager;
11	        this.socket = io('//multiplayer.shcux.de', { transports: ['websocket', 'polling'] });
12	        
13	        this.setupBroadcastChannel();
14	        this.setupSocketListeners();
15	        this.setupPeriodicBroadcast();
16	        this.setupConnectionMonitor();
17	    }
18	    
19	    setupBroadcastChannel() {
20	        this.broadcastChannel = new BroadcastChannel('penguin_multiplayer');
21	        this.broadcastChannel.onmessage = (e) => {
22	            if (e.data && e.data.id === this.manager.myPenguinId) {
23	                if (e.data.type === 'takeover') {
24	                    this.manager.isPassive = true;
25	                } else if (e.data.type === 'remove') {
26	                    this.manager.handleLocalPenguinRemoval();
27	                }
28	            }
29	        };
30	        
31	        window.addEventListener('focus', () => {
32	            if (this.manager.hasJoined && this.manager.isPassive) {
33	                this.manager.isPassive = false;
34	                this.broadcastChannel.postMessage({ type: 'takeover', id: this.manager.myPenguinId });
35	            }
36	        });
37	    }
38	    
39	    setupSocketListeners() {
40	        this.socket.on('assignName', (data) => {
41	            console.log('Server assigned new name:', data.name);
42	            this.manager.myPenguinName = data.name;
43	            localStorage.setItem('penguinName', data.name);
44	            const player = this.manager.penguins.find(p => p.isPlayer);
45	            if (player) {
46	                player.name = data.name;
47	                if (player.nameTag) player.nameTag.textContent = data.name;
48	                // Re-broadcast state immediately with the new authoritative name
49	                this.broadcastCurrentState();
50	            }
51	        });
52	
53	        this.socket.on('initialState', (state) => {
54	            // Clear ghosts on reconnect
55	            for (let key in this.manager.remotePenguins) {
56	                this.manager.remotePenguins[key].remove();
57	                delete this.manager.remotePenguins[key];
58	            }
59	            this.manager.enemies.clear();
60	            if (state.globalFishCount !== undefined) {
61	                this.manager.ui.updateScore(state.globalFishCount);
62	            }
63	
64	            // Spawn stationary powerups
65	            if (state.stationaryPowerUps) {
66	                state.stationaryPowerUps.forEach(pu => {
67	                    // Convert relative X back to header relative
68	                    const absX = (1290 / 2) + pu.x;
69	                    this.manager.spawnPowerUpFish(absX, pu.y, pu.type, pu.world || 'lobby', pu.id);
70	                });
71	            }
72	
73	            // Spawn active global fish
74	            if (state.goldenFishActive && state.goldenFishData) {
75	                const absX = (1290 / 2) + state.goldenFishData.x;
76	                this.manager.spawnGoldenFish(absX, state.goldenFishData.y, state.goldenFishData.world || 'lobby');
77	            }
78	
79	            // Spawn active global powerup
80	            if (state.powerUpActive && state.powerUpData) {
81	                const absX = (1290 / 2) + state.powerUpData.x;
82	                this.manager.spawnPowerUpFish(absX, state.powerUpData.y, state.powerUpData.type, state.powerUpData.world || 'lobby');
83	            }
84	
85	            // Spawn current server enemies
86	            if (state.enemies) {
87	                state.enemies.forEach(enemy => this.manager.enemies.upsert(enemy));
88	            }
89	            
90	            // Auto-join/control if our penguin is already active on the server
91	            if (state.penguins && state.penguins[this.manager.myPenguinId]) {
92	                const data = state.penguins[this.manager.myPenguinId];
93	                if (!this.manager.hasJoined && this.manager.penguins.length === 0) {
94	                    this.manager.autoJoin(data);
95	                }
96	            }
97	        });
98	        
99	        this.socket.on('penguinUpdated', (data) => {
100	            if (data.id === this.manager.myPenguinId) return;
101	            
102	            if (!this.manager.remotePenguins[data.id]) {
103	                const rp = new RemotePenguin(data, this.manager);
104	                this.manager.remotePenguins[data.id] = rp;
105	                
106	                const header = document.querySelector('#header .inner-header') || document.getElementById('header');
107	                const container = header || document.body;
108	                container.appendChild(rp.element);
109	            }
110	            this.manager.remotePenguins[data.id].updateData(data);
111	        });
112	        
113	        this.socket.on('penguinRemoved', (id) => {
114	            if (id === this.manager.myPenguinId) return;
115	            
116	            if (this.manager.remotePenguins[id]) {
117	                this.manager.effects.spawnCloudExplosion(this.manager.remotePenguins[id].x, this.manager.remotePenguins[id].y);
118	                this.manager.remotePenguins[id].remove();
119	                delete this.manager.remotePenguins[id];
120	            }
121	        });
122	        
123	        this.socket.on('enemyUpdated', (data) => {
124	            this.manager.enemies.upsert(data);
125	        });
126	        
127	        this.socket.on('enemyRemoved', (id) => {
128	            this.manager.enemies.remove(id);
129	        });
130	        
131	        this.socket.on('penguinEmote', (data) => {
132	            if (this.manager.remotePenguins[data.id]) {
133	                this.manager.remotePenguins[data.id].popEmote(data.emote);
134	            }
135	        });
136	
137	        this.socket.on('deathCause', (data) => {
138	            const rp = this.manager.remotePenguins[data.id];
139	            if (rp) rp.showDeathCause(data.cause);
140	
141	            // Only spawn the particle burst if the dying penguin is in our
142	            // current world (otherwise it'd flash at a meaningless coordinate).
143	            const localPlayer = this.manager.penguins.find(p => p.isPlayer);
144	            const localWorld = localPlayer ? (localPlayer.currentWorld || 'lobby') : 'lobby';
145	            if (!rp || (rp.world || 'lobby') !== localWorld) return;
146	
147	            if (data.x !== undefined && data.y !== undefined) {
148	                const absX = (1290 / 2) + data.x;
149	                const absY = this.manager.getRelativeFloorY() + data.y;
150	                this.manager.effects.spawnPenguinExplosion(absX, absY);
151	            } else {
152	                this.manager.effects.spawnPenguinExplosion(rp.x, rp.y);
153	            }
154	        });
155	
156	        this.socket.on('snowballThrown', (data) => {
157	            const internalCenterX = 1290 / 2;
158	            const absoluteX = internalCenterX + data.x;
159	            this.manager.spawnSnowball(absoluteX, data.y, data.direction, data.id, undefined, data.world, data.vy, data.gravity);
160	        });
161	
162	        this.socket.on('playerFrozen', (data) => {
163	            const localPlayer = this.manager.penguins.find(p => p.id === data.id);
164	            if (localPlayer) {
165	                if (localPlayer.powerUpType === 'shield') {
166	                    localPlayer.powerUpType = null;
167	                    localPlayer.powerUpTimer = 0;
168	                    this.manager.effects.spawnStarExplosion(localPlayer.x, localPlayer.y);
169	                } else if (localPlayer.powerUpType === 'giant') {
170	                    // Giant immune locally too!
171	                    this.manager.effects.spawnStarExplosion(localPlayer.x, localPlayer.y);
172	                } else {
173	                    localPlayer.freeze(data.duration);
174	                }
175	            } else if (this.manager.remotePenguins[data.id]) {
176	                const rp = this.manager.remotePenguins[data.id];
177	                if (rp.powerUpType === 'shield') {
178	                    rp.powerUpType = null;
179	                    this.manager.effects.spawnStarExplosion(rp.x, rp.y);
180	                } else if (rp.powerUpType === 'giant') {
181	                    // Giant immune locally too!
182	                    this.manager.effects.spawnStarExplosion(rp.x, rp.y);
183	                } else {
184	                    rp.freeze(data.duration);
185	                }
186	            }
187	
188	            // Instantly and deterministically destroy the exact snowball by its unique ID on everyone's screen
189	            if (data.snowballId) {
190	                this.manager.destroySnowballById(data.snowballId);
191	            } else {
192	                // Fallback to coordinates-based nearby cleanup if no ID is present (e.g. legacy/server bot)
193	                const target = localPlayer || this.manager.remotePenguins[data.id];
194	                if (target) {
195	                    this.manager.destroyNearbySnowball(target.x, target.y);
196	                }
197	            }
198	        });
199	
200	        this.socket.on('updateDuelScore', (data) => {
201	            if (data.active && this.manager.hasJoined) { // Only show HUD if we have actually joined!
202	                this.manager.duelPlayerScore = data.playerScore;
203	                this.manager.duelBotScore = data.botScore;
204	                this.manager.ui.showDuelHUD();
205	            } else {
206	                this.manager.ui.hideDuelHUD();
207	            }
208	        });
209	        
210	        this.socket.on('spawnFish', (data) => {
211	            const internalCenterX = 1290 / 2;
212	            const absoluteX = internalCenterX + data.x;
213	            this.manager.spawnGoldenFish(absoluteX, data.y, data.world || 'lobby');
214	        });
215	        
216	        this.socket.on('despawnFish', () => {
217	            this.manager.removeGoldenFish();
218	        });
219	
220	        this.socket.on('spawnPowerUp', (data) => {
221	            const absX = (1290 / 2) + data.x;
222	            this.manager.spawnPowerUpFish(absX, data.y, data.type, data.world || 'lobby', data.id);
223	        });
224	
225	        this.socket.on('despawnPowerUp', () => {
226	            this.manager.removePowerUpFish();
227	        });
228	
229	        this.socket.on('powerUpCaught', (data) => {
230	            if (this.manager.powerUpFish) {
231	                this.manager.effects.spawnStarExplosion(this.manager.puX, this.manager.puY);
232	            }
233	            this.manager.removePowerUpFish();
234	            
235	            // Also hide local test powerup if someone else caught it at its fixed location
236	            this.manager.hideTestPowerUpByType(data.type);
237	        });
238	        
239	        this.socket.on('fishCaught', (data) => {
240	            if (this.manager.goldenFish) {
241	                this.manager.effects.spawnStarExplosion(this.manager.fishX, this.manager.fishY);
242	            }
243	            this.manager.removeGoldenFish();
244	            this.manager.ui.updateScore(data.globalFishCount);
245	        });
246	        
247	        this.socket.on('leaderboard', (sorted) => {
248	            this.manager.ui.updateLeaderboard(sorted);
249	        });
250	
251	        this.socket.on('personalScore', (data) => {
252	            this.manager.fishCount = data.score;
253	            this.manager.ui.updatePersonalScore(data.score);
254	        });
255	
256	        this.socket.on('goldenFishScore', (data) => {
257	            this.manager.goldenFishCount = data.score;
258	            this.manager.ui.updateGoldenFishScore(data.score);
259	        });
260	
261	        this.socket.on('inventoryUpdate', (data) => {
262	            this.manager.inventory = data.inventory;
263	            this.manager.ui.renderInventory();
264	        });
265	
266	        this.socket.on('activeHatUpdate', (data) => {
267	            const player = this.manager.penguins.find(p => p.isPlayer);
268	            if (player) {
269	                player.activeHat = data.activeHat;
270	            }
271	        });
272	
273	        this.socket.on('activeColorUpdate', (data) => {
274	            const player = this.manager.penguins.find(p => p.isPlayer);
275	            if (player) {
276	                player.activeColor = data.activeColor;
277	            }
278	        });
279	
280	        this.socket.on('activeGlassesUpdate', (data) => {
281	            const player = this.manager.penguins.find(p => p.isPlayer);
282	            if (player) {
283	                player.activeGlasses = !!data.activeGlasses;
284	            }
285	        });
286	
287	        this.socket.on('worldItems', (items) => {
288	            items.forEach(item => this.manager.spawnWorldItem(item));
289	        });
290	
291	        this.socket.on('itemSpawned', (item) => {
292	            this.manager.spawnWorldItem(item);
293	        });
294	
295	        this.socket.on('itemDespawned', (data) => {
296	            this.manager.removeWorldItem(data.itemId);
297	        });
298	
299	        this.socket.on('iceCubes', (cubes) => {
300	            cubes.forEach(c => this.manager.iceCubes.spawnIceCube(c));
301	        });
302	
303	        this.socket.on('iceCubePlaced', (cube) => {
304	            this.manager.iceCubes.spawnIceCube(cube);
305	        });
306	
307	        this.socket.on('iceCubeDestroyed', (data) => {
308	            if (data.crush) {
309	                this.manager.iceCubes.crushIceCubeRemote(data.id);
310	            } else {
311	                this.manager.iceCubes.removeIceCube(data.id, data.pop !== false);
312	            }
313	        });
314	
315	        this.socket.on('iceCubeCracked', (data) => {
316	            this.manager.iceCubes.crackIceCube(data.id);
317	        });
318	
319	        this.socket.on('iceCubeSettled', (cubes) => {
320	            (cubes || []).forEach(c => this.manager.iceCubes.applySettled(c));
321	        });
322	
323	        this.socket.on('topCatcher', (data) => {
324	            this.manager.ui.updateTopCatcher(data.name, data.score);
325	        });
326	
327	        this.socket.on('serverFull', () => {
328	            this.manager.ui.showServerFullMessage();
329	            this.socket.disconnect();
330	            this.manager.handleLocalPenguinRemoval();
331	        });
332	    }
333	
334	    setupConnectionMonitor() {
335	        this.socket.on('connect', () => {
336	            console.log('Socket connected/reconnected');
337	            // If we have a penguin, instantly tell the server we're here
338	            this.broadcastCurrentState();
339	        });
340	
341	        this.socket.on('reconnect', () => {
342	            console.log('Socket reconnected');
343	            this.broadcastCurrentState();
344	        });
345	    }
346	
347	    broadcastCurrentState() {
348	        if (this.manager.isPassive) return;
349	        
350	        // Internal coordinate system is 0-1290 (header relative)
351	        // Network coordinate system is offset from header center
352	        const internalCenterX = 1290 / 2;
353	        const relativeFloorY = this.manager.getRelativeFloorY();
354	
355	        for (let p of this.manager.penguins) {
356	            // Build mode (ice-cube placement): share the ghost preview so other
357	            // players see the dashed square this penguin is about to place.
358	            let buildMode = false;
359	            let buildGhostX = 0;
360	            let buildGhostY = 0;
361	            let buildGhostValid = false;
362	            if (p.isPlayer && this.manager.iceCubes && this.manager.iceCubes.armed) {
363	                const pos = this.manager.iceCubes.computePlacement(p);
364	                buildMode = true;
365	                buildGhostX = pos.x - internalCenterX;
366	                buildGhostY = pos.y - relativeFloorY;
367	                buildGhostValid = this.manager.iceCubes.isPlaceable(pos.x, pos.y, p);
368	            }
369	            this.socket.emit('updatePenguin', {
370	                id: p.id,
371	                secret: this.manager.myPenguinSecret,
372	                x: p.x - internalCenterX, // Send relative X
373	                y: p.y - relativeFloorY,  // Send floor-relative Y offset (normalized for Mobile/Desktop)
374	                state: p.state,
375	                direction: p.direction,
376	                scale: p.scale,
377	                opacity: p.opacity,
378	                name: p.name,
379	                powerUpType: p.powerUpType,
380	                pancakeTimer: p.pancakeTimer,
381	                activeColor: p.activeColor,
382	                swimming: p.swimming,
383	                world: p.currentWorld || 'lobby',
384	                buildMode: buildMode,
385	                buildGhostX: buildGhostX,
386	                buildGhostY: buildGhostY,
387	                buildGhostValid: buildGhostValid
388	            });
389	        }
390	    }
391	    
392	    setupPeriodicBroadcast() {
393	        setInterval(() => {
394	            this.broadcastCurrentState();
395	        }, GameConfig.NETWORK_UPDATE_INTERVAL);
396	
397	        // Explicit Heartbeat to keep connection alive and server aware
398	        setInterval(() => {
399	            if (this.manager.hasJoined && !this.manager.isPassive) {
400	                this.socket.emit('ping_presence', { id: this.manager.myPenguinId });
401	            }
402	        }, 2000);
403	    }
404	    
405	    emitEmote(id, emote) {
406	        this.socket.emit('emote', { id, secret: this.manager.myPenguinSecret, emote });
407	    }
408	
409	    emitDeathCause(id, cause, x, y) {
410	        const internalCenterX = 1290 / 2;
411	        const relativeFloorY = this.manager.getRelativeFloorY();
412	        this.socket.emit('deathCause', {
413	            id,
414	            secret: this.manager.myPenguinSecret,
415	            cause,
416	            x: x !== undefined ? x - internalCenterX : undefined,
417	            y: y !== undefined ? y - relativeFloorY : undefined
418	        });
419	    }
420	    
421	    emitCatchFish(id, name) {
422	        this.socket.emit('catchFish', { id, secret: this.manager.myPenguinSecret, name });
423	    }
424	
425	    emitCatchPowerUp(id, type) {
426	        this.socket.emit('catchPowerUp', { id, secret: this.manager.myPenguinSecret, type });
427	    }
428	    
429	    emitRemovePenguin(id) {
430	        this.socket.emit('removePenguin', { id, secret: this.manager.myPenguinSecret });
431	    }
432	
433	    emitThrowSnowball(x, y, direction, ownerId, snowballId) {
434	        const internalCenterX = 1290 / 2;
435	        this.socket.emit('throwSnowball', { x: x - internalCenterX, y, direction, id: ownerId, secret: this.manager.myPenguinSecret, snowballId: snowballId });
436	    }
437	
438	    // Registers a world's enemy list (authored in the Level Editor / WORLDS) with
439	    // the server. World coords (X 0..1290) are converted to center-relative
440	    // network coords before sending.
441	    emitRegisterEnemies(world, enemies) {
442	        const internalCenterX = 1290 / 2;
443	        this.socket.emit('registerEnemies', {
444	            id: this.manager.myPenguinId,
445	            secret: this.manager.myPenguinSecret,
446	            world: world || 'lobby',
447	            width: this.manager.getWorldWidth(world) || 1290,
448	            enemies: (enemies || []).map(e => {
449	                const x = e.x || 0;
450	                return {
451	                    id: e.id,
452	                    type: e.type,
453	                    label: e.label || '',
454	                    x: x - internalCenterX,
455	                    patrolX1: (e.patrolX1 !== undefined ? e.patrolX1 : x - 150) - internalCenterX,
456	                    patrolX2: (e.patrolX2 !== undefined ? e.patrolX2 : x + 150) - internalCenterX,
457	                    persistent: !!e.persistent,
458	                    aggressive: !!e.aggressive,
459	                    retaliate: !!e.retaliate,
460	                    retaliateTime: e.retaliateTime !== undefined ? e.retaliateTime : 15,
461	                    fireRate: e.fireRate !== undefined ? e.fireRate : 2.0,
462	                    volley: e.volley !== undefined ? e.volley : 1,
463	                    color: e.color || ''
464	                };
465	            })
466	        });
467	    }
468	
469	    // Registers a world's static platforms (WORLDS / editor maps) with the
470	    // server so server-side enemies can collide with them. World coords are
471	    // converted to network coords (x center-relative, y floor-relative).
472	    emitRegisterPlatforms(world, platforms) {
473	        const internalCenterX = 1290 / 2;
474	        const floorY = this.manager.getRelativeFloorY();
475	        this.socket.emit('registerPlatforms', {
476	            id: this.manager.myPenguinId,
477	            secret: this.manager.myPenguinSecret,
478	            world: world || 'lobby',
479	            platforms: (platforms || []).map(p => ({
480	                id: p.id,
481	                x1: (p.x1 !== undefined ? p.x1 : 0) - internalCenterX,
482	                x2: (p.x2 !== undefined ? p.x2 : 0) - internalCenterX,
483	                y1: (p.y1 !== undefined ? p.y1 : 0) - floorY,
484	                y2: (p.y2 !== undefined ? p.y2 : 0) - floorY,
485	                h: p.h || 10,
486	                isSolid: !!p.isSolid,
487	            })),
488	        });
489	    }
490	
491	    emitFreeze(id, duration, attackerId, snowballId = null) {
492	        this.socket.emit('freezePlayer', { 
493	            id, 
