/**
 * NetworkManager.js
 * Handles Socket.io and BroadcastChannel communication.
 */
import { RemotePenguin } from './RemotePenguin.js';
import { GameConfig } from './GameConfig.js';

export class NetworkManager {
    constructor(manager) {
        this.manager = manager;
        this.socket = io('//multiplayer.shcux.de', { transports: ['websocket', 'polling'] });

        this.setupBroadcastChannel();
        this.setupSocketListeners();
        this.setupPeriodicBroadcast();
        this.setupConnectionMonitor();
    }

    setupBroadcastChannel() {
        this.broadcastChannel = new BroadcastChannel('penguin_multiplayer');
        this.broadcastChannel.onmessage = (e) => {
            if (e.data && e.data.id === this.manager.myPenguinId) {
                if (e.data.type === 'takeover') {
                    this.manager.isPassive = true;
                } else if (e.data.type === 'remove') {
                    this.manager.handleLocalPenguinRemoval();
                }
            }
        };

        window.addEventListener('focus', () => {
            if (this.manager.hasJoined && this.manager.isPassive) {
                this.manager.isPassive = false;
                this.broadcastChannel.postMessage({ type: 'takeover', id: this.manager.myPenguinId });
            }
        });
    }

    setupSocketListeners() {
        this.socket.on('assignName', (data) => {
            console.log('Server assigned new name:', data.name);
            this.manager.myPenguinName = data.name;
            localStorage.setItem('penguinName', data.name);
            const player = this.manager.penguins.find(p => p.isPlayer);
            if (player) {
                player.name = data.name;
                if (player.nameTag) player.nameTag.textContent = data.name;
                // Re-broadcast state immediately with the new authoritative name
                this.broadcastCurrentState();
            }
        });

        this.socket.on('initialState', (state) => {
            // Clear ghosts on reconnect
            for (let key in this.manager.remotePenguins) {
                this.manager.remotePenguins[key].remove();
                delete this.manager.remotePenguins[key];
            }
            this.manager.enemies.clear();
            if (state.globalFishCount !== undefined) {
                this.manager.ui.updateScore(state.globalFishCount);
            }

            // Spawn stationary powerups
            if (state.stationaryPowerUps) {
                state.stationaryPowerUps.forEach(pu => {
                    // Convert relative X back to header relative
                    const absX = (1290 / 2) + pu.x;
                    this.manager.spawnPowerUpFish(absX, pu.y, pu.type, pu.world || 'lobby', pu.id);
                });
            }

            // Spawn active global fish
            if (state.goldenFishActive && state.goldenFishData) {
                const absX = (1290 / 2) + state.goldenFishData.x;
                this.manager.spawnGoldenFish(absX, state.goldenFishData.y, state.goldenFishData.world || 'lobby');
            }

            // Spawn active global powerup
            if (state.powerUpActive && state.powerUpData) {
                const absX = (1290 / 2) + state.powerUpData.x;
                this.manager.spawnPowerUpFish(absX, state.powerUpData.y, state.powerUpData.type, state.powerUpData.world || 'lobby');
            }

            // Spawn current server enemies
            if (state.enemies) {
                state.enemies.forEach(enemy => this.manager.enemies.upsert(enemy));
            }

            // Auto-join/control if our penguin is already active on the server
            if (state.penguins && state.penguins[this.manager.myPenguinId]) {
                const data = state.penguins[this.manager.myPenguinId];
                if (!this.manager.hasJoined && this.manager.penguins.length === 0) {
                    this.manager.autoJoin(data);
                }
            }
        });

        this.socket.on('penguinUpdated', (data) => {
            if (data.id === this.manager.myPenguinId) return;

            if (!this.manager.remotePenguins[data.id]) {
                const rp = new RemotePenguin(data, this.manager);
                this.manager.remotePenguins[data.id] = rp;

                const header = document.querySelector('#header .inner-header') || document.getElementById('header');
                const container = header || document.body;
                container.appendChild(rp.element);
            }
            this.manager.remotePenguins[data.id].updateData(data);
        });

        this.socket.on('penguinRemoved', (id) => {
            if (id === this.manager.myPenguinId) return;

            if (this.manager.remotePenguins[id]) {
                this.manager.effects.spawnCloudExplosion(this.manager.remotePenguins[id].x, this.manager.remotePenguins[id].y);
                this.manager.remotePenguins[id].remove();
                delete this.manager.remotePenguins[id];
            }
        });

        this.socket.on('enemyUpdated', (data) => {
            this.manager.enemies.upsert(data);
        });

        this.socket.on('enemyRemoved', (id) => {
            this.manager.enemies.remove(id);
        });

        this.socket.on('penguinEmote', (data) => {
            if (this.manager.remotePenguins[data.id]) {
                this.manager.remotePenguins[data.id].popEmote(data.emote);
            }
        });

        this.socket.on('deathCause', (data) => {
            const rp = this.manager.remotePenguins[data.id];
            if (rp) rp.showDeathCause(data.cause);

            // Only spawn the particle burst if the dying penguin is in our
            // current world (otherwise it'd flash at a meaningless coordinate).
            const localPlayer = this.manager.penguins.find(p => p.isPlayer);
            const localWorld = localPlayer ? (localPlayer.currentWorld || 'lobby') : 'lobby';
            if (!rp || (rp.world || 'lobby') !== localWorld) return;

            if (data.x !== undefined && data.y !== undefined) {
                const absX = (1290 / 2) + data.x;
                const absY = this.manager.getRelativeFloorY() + data.y;
                this.manager.effects.spawnPenguinExplosion(absX, absY);
            } else {
                this.manager.effects.spawnPenguinExplosion(rp.x, rp.y);
            }
        });

        this.socket.on('snowballThrown', (data) => {
            const internalCenterX = 1290 / 2;
            const absoluteX = internalCenterX + data.x;
            this.manager.spawnSnowball(absoluteX, data.y, data.direction, data.id, undefined, data.world, data.vy, data.gravity);
        });

        this.socket.on('playerFrozen', (data) => {
            const localPlayer = this.manager.penguins.find(p => p.id === data.id);
            if (localPlayer) {
                if (localPlayer.powerUpType === 'shield') {
                    localPlayer.powerUpType = null;
                    localPlayer.powerUpTimer = 0;
                    this.manager.effects.spawnStarExplosion(localPlayer.x, localPlayer.y);
                } else if (localPlayer.powerUpType === 'giant') {
                    // Giant immune locally too!
                    this.manager.effects.spawnStarExplosion(localPlayer.x, localPlayer.y);
                } else {
                    localPlayer.freeze(data.duration);
                }
            } else if (this.manager.remotePenguins[data.id]) {
                const rp = this.manager.remotePenguins[data.id];
                if (rp.powerUpType === 'shield') {
                    rp.powerUpType = null;
                    this.manager.effects.spawnStarExplosion(rp.x, rp.y);
                } else if (rp.powerUpType === 'giant') {
                    // Giant immune locally too!
                    this.manager.effects.spawnStarExplosion(rp.x, rp.y);
                } else {
                    rp.freeze(data.duration);
                }
            }

            // Instantly and deterministically destroy the exact snowball by its unique ID on everyone's screen
            if (data.snowballId) {
                this.manager.destroySnowballById(data.snowballId);
            } else {
                // Fallback to coordinates-based nearby cleanup if no ID is present (e.g. legacy/server bot)
                const target = localPlayer || this.manager.remotePenguins[data.id];
                if (target) {
                    this.manager.destroyNearbySnowball(target.x, target.y);
                }
            }
        });

        this.socket.on('updateDuelScore', (data) => {
            if (data.active && this.manager.hasJoined) { // Only show HUD if we have actually joined!
                this.manager.duelPlayerScore = data.playerScore;
                this.manager.duelBotScore = data.botScore;
                this.manager.ui.showDuelHUD();
            } else {
                this.manager.ui.hideDuelHUD();
            }
        });

        this.socket.on('spawnFish', (data) => {
            const internalCenterX = 1290 / 2;
            const absoluteX = internalCenterX + data.x;
            this.manager.spawnGoldenFish(absoluteX, data.y, data.world || 'lobby');
        });

        this.socket.on('despawnFish', () => {
            this.manager.removeGoldenFish();
        });

        this.socket.on('spawnPowerUp', (data) => {
            const absX = (1290 / 2) + data.x;
            this.manager.spawnPowerUpFish(absX, data.y, data.type, data.world || 'lobby', data.id);
        });

        this.socket.on('despawnPowerUp', () => {
            this.manager.removePowerUpFish();
        });

        this.socket.on('powerUpCaught', (data) => {
            if (this.manager.powerUpFish) {
                this.manager.effects.spawnStarExplosion(this.manager.puX, this.manager.puY);
            }
            this.manager.removePowerUpFish();

            // Also hide local test powerup if someone else caught it at its fixed location
            this.manager.hideTestPowerUpByType(data.type);
        });

        this.socket.on('fishCaught', (data) => {
            if (this.manager.goldenFish) {
                this.manager.effects.spawnStarExplosion(this.manager.fishX, this.manager.fishY);
            }
            this.manager.removeGoldenFish();
            this.manager.ui.updateScore(data.globalFishCount);
        });

        this.socket.on('leaderboard', (sorted) => {
            this.manager.ui.updateLeaderboard(sorted);
        });

        this.socket.on('personalScore', (data) => {
            this.manager.fishCount = data.score;
            this.manager.ui.updatePersonalScore(data.score);
        });

        this.socket.on('goldenFishScore', (data) => {
            this.manager.goldenFishCount = data.score;
            this.manager.ui.updateGoldenFishScore(data.score);
        });

        this.socket.on('inventoryUpdate', (data) => {
            this.manager.inventory = data.inventory;
            this.manager.ui.renderInventory();
        });

        this.socket.on('activeHatUpdate', (data) => {
            const player = this.manager.penguins.find(p => p.isPlayer);
            if (player) {
                player.activeHat = data.activeHat;
            }
        });

        this.socket.on('activeColorUpdate', (data) => {
            const player = this.manager.penguins.find(p => p.isPlayer);
            if (player) {
                player.activeColor = data.activeColor;
            }
        });

        this.socket.on('activeGlassesUpdate', (data) => {
            const player = this.manager.penguins.find(p => p.isPlayer);
            if (player) {
                player.activeGlasses = !!data.activeGlasses;
            }
        });

        this.socket.on('worldItems', (items) => {
            items.forEach(item => this.manager.spawnWorldItem(item));
        });

        this.socket.on('itemSpawned', (item) => {
            this.manager.spawnWorldItem(item);
        });

        this.socket.on('itemDespawned', (data) => {
            this.manager.removeWorldItem(data.itemId);
        });

        this.socket.on('iceCubes', (cubes) => {
            cubes.forEach(c => this.manager.iceCubes.spawnIceCube(c));
        });

        this.socket.on('iceCubePlaced', (cube) => {
            this.manager.iceCubes.spawnIceCube(cube);
        });

        this.socket.on('iceCubeDestroyed', (data) => {
            if (data.crush) {
                this.manager.iceCubes.crushIceCubeRemote(data.id);
            } else {
                this.manager.iceCubes.removeIceCube(data.id, data.pop !== false);
            }
        });

        this.socket.on('iceCubeCracked', (data) => {
            this.manager.iceCubes.crackIceCube(data.id);
        });

        this.socket.on('iceCubeSettled', (cubes) => {
            (cubes || []).forEach(c => this.manager.iceCubes.applySettled(c));
        });

        this.socket.on('topCatcher', (data) => {
            this.manager.ui.updateTopCatcher(data.name, data.score);
        });

        this.socket.on('serverFull', () => {
            this.manager.ui.showServerFullMessage();
            this.socket.disconnect();
            this.manager.handleLocalPenguinRemoval();
        });
    }

    setupConnectionMonitor() {
        this.socket.on('connect', () => {
            console.log('Socket connected/reconnected');
            // If we have a penguin, instantly tell the server we're here
            this.broadcastCurrentState();
        });

        this.socket.on('reconnect', () => {
            console.log('Socket reconnected');
            this.broadcastCurrentState();
        });
    }

    broadcastCurrentState() {
        if (this.manager.isPassive) return;

        // Internal coordinate system is 0-1290 (header relative)
        // Network coordinate system is offset from header center
        const internalCenterX = 1290 / 2;
        const relativeFloorY = this.manager.getRelativeFloorY();

        for (let p of this.manager.penguins) {
            // Build mode (ice-cube placement): share the ghost preview so other
            // players see the dashed square this penguin is about to place.
            let buildMode = false;
            let buildGhostX = 0;
            let buildGhostY = 0;
            let buildGhostValid = false;
            if (p.isPlayer && this.manager.iceCubes && this.manager.iceCubes.armed) {
                const pos = this.manager.iceCubes.computePlacement(p);
                buildMode = true;
                buildGhostX = pos.x - internalCenterX;
                buildGhostY = pos.y - relativeFloorY;
                buildGhostValid = this.manager.iceCubes.isPlaceable(pos.x, pos.y, p);
            }
            this.socket.emit('updatePenguin', {
                id: p.id,
                secret: this.manager.myPenguinSecret,
                x: p.x - internalCenterX, // Send relative X
                y: p.y - relativeFloorY,  // Send floor-relative Y offset (normalized for Mobile/Desktop)
                state: p.state,
                direction: p.direction,
                scale: p.scale,
                opacity: p.opacity,
                name: p.name,
                powerUpType: p.powerUpType,
                pancakeTimer: p.pancakeTimer,
                activeColor: p.activeColor,
                swimming: p.swimming,
                world: p.currentWorld || 'lobby',
                buildMode: buildMode,
                buildGhostX: buildGhostX,
                buildGhostY: buildGhostY,
                buildGhostValid: buildGhostValid
            });
        }
    }

    setupPeriodicBroadcast() {
        setInterval(() => {
            this.broadcastCurrentState();
        }, GameConfig.NETWORK_UPDATE_INTERVAL);

        // Explicit Heartbeat to keep connection alive and server aware
        setInterval(() => {
            if (this.manager.hasJoined && !this.manager.isPassive) {
                this.socket.emit('ping_presence', { id: this.manager.myPenguinId });
            }
        }, 2000);
    }

    emitEmote(id, emote) {
        this.socket.emit('emote', { id, secret: this.manager.myPenguinSecret, emote });
    }

    emitDeathCause(id, cause, x, y) {
        const internalCenterX = 1290 / 2;
        const relativeFloorY = this.manager.getRelativeFloorY();
        this.socket.emit('deathCause', {
            id,
            secret: this.manager.myPenguinSecret,
            cause,
            x: x !== undefined ? x - internalCenterX : undefined,
            y: y !== undefined ? y - relativeFloorY : undefined
        });
    }

    emitCatchFish(id, name) {
        this.socket.emit('catchFish', { id, secret: this.manager.myPenguinSecret, name });
    }

    emitCatchPowerUp(id, type) {
        this.socket.emit('catchPowerUp', { id, secret: this.manager.myPenguinSecret, type });
    }

    emitRemovePenguin(id) {
        this.socket.emit('removePenguin', { id, secret: this.manager.myPenguinSecret });
    }

    emitThrowSnowball(x, y, direction, ownerId, snowballId) {
        const internalCenterX = 1290 / 2;
        this.socket.emit('throwSnowball', { x: x - internalCenterX, y, direction, id: ownerId, secret: this.manager.myPenguinSecret, snowballId: snowballId });
    }

    // Registers a world's enemy list (authored in the Level Editor / WORLDS) with
    // the server. World coords (X 0..1290) are converted to center-relative
    // network coords before sending.
    emitRegisterEnemies(world, enemies) {
        const internalCenterX = 1290 / 2;
        this.socket.emit('registerEnemies', {
            id: this.manager.myPenguinId,
            secret: this.manager.myPenguinSecret,
            world: world || 'lobby',
            width: this.manager.getWorldWidth(world) || 1290,
            enemies: (enemies || []).map(e => {
                const x = e.x || 0;
                return {
                    id: e.id,
                    type: e.type,
                    label: e.label || '',
                    x: x - internalCenterX,
                    patrolX1: (e.patrolX1 !== undefined ? e.patrolX1 : x - 150) - internalCenterX,
                    patrolX2: (e.patrolX2 !== undefined ? e.patrolX2 : x + 150) - internalCenterX,
                    persistent: !!e.persistent,
                    aggressive: !!e.aggressive,
                    retaliate: !!e.retaliate,
                    retaliateTime: e.retaliateTime !== undefined ? e.retaliateTime : 15,
                    fireRate: e.fireRate !== undefined ? e.fireRate : 2.0,
                    volley: e.volley !== undefined ? e.volley : 1,
                    color: e.color || ''
                };
            })
        });
    }

    // Registers a world's static platforms (WORLDS / editor maps) with the
    // server so server-side enemies can collide with them. World coords are
    // converted to network coords (x center-relative, y floor-relative).
    emitRegisterPlatforms(world, platforms) {
        const internalCenterX = 1290 / 2;
        const floorY = this.manager.getRelativeFloorY();
        this.socket.emit('registerPlatforms', {
            id: this.manager.myPenguinId,
            secret: this.manager.myPenguinSecret,
            world: world || 'lobby',
            platforms: (platforms || []).map(p => ({
                id: p.id,
                x1: (p.x1 !== undefined ? p.x1 : 0) - internalCenterX,
                x2: (p.x2 !== undefined ? p.x2 : 0) - internalCenterX,
                y1: (p.y1 !== undefined ? p.y1 : 0) - floorY,
                y2: (p.y2 !== undefined ? p.y2 : 0) - floorY,
                h: p.h || 10,
                isSolid: !!p.isSolid,
            })),
        });
    }

    emitFreeze(id, duration, attackerId, snowballId = null) {
        this.socket.emit('freezePlayer', { 
            id, 
            duration, 
            secret: this.manager.myPenguinSecret, 
            snowballId: snowballId,
            attackerId: attackerId,
            attackerSecret: this.manager.myPenguinSecret
        });
    }

    broadcastTakeover(id) {
        this.broadcastChannel.postMessage({ type: 'takeover', id });
    }

    broadcastRemove(id) {
        this.broadcastChannel.postMessage({ type: 'remove', id });
    }

    emitDropItem(slotIndex, id, secret) {
        this.socket.emit('dropItem', { slotIndex, id, secret });
    }

    emitPickUpItem(itemId, id, secret) {
        this.socket.emit('pickUpItem', { itemId, id, secret });
    }

    emitUseItem(slotIndex, id, secret) {
        this.socket.emit('useItem', { slotIndex, id, secret });
    }

    emitToggleWearable(slotIndex, id, secret) {
        this.socket.emit('toggleWearable', { slotIndex, id, secret });
    }

    emitTestAddItem(itemType) {
        this.socket.emit('test_addItem', {
            id: this.manager.myPenguinId,
            secret: this.manager.myPenguinSecret,
            itemType: itemType
        });
    }

    emitBuyItem(itemId) {
        this.socket.emit('buy_item', {
            id: this.manager.myPenguinId,
            secret: this.manager.myPenguinSecret,
            itemId: itemId
        });
    }

    emitPlaceIceCube(x, y, world) {
        const internalCenterX = 1290 / 2;
        this.socket.emit('placeIceCube', {
            id: this.manager.myPenguinId,
            secret: this.manager.myPenguinSecret,
            x: x - internalCenterX,
            y: y - this.manager.getRelativeFloorY(),
            world: world || 'lobby',
            width: this.manager.getWorldWidth(world) || 1290
        });
    }

    emitIceCubeSync(cubes) {
        const internalCenterX = 1290 / 2;
        const floorY = this.manager.getRelativeFloorY();
        this.socket.emit('iceCubeSync', {
            id: this.manager.myPenguinId,
            secret: this.manager.myPenguinSecret,
            cubes: cubes.map(c => ({
                id: c.id,
                x: c.x - internalCenterX,
                y: c.y - floorY,
                world: c.world || 'lobby',
                width: this.manager.getWorldWidth(c.world) || 1290
            }))
        });
    }

    emitDestroyIceCube(cubeId, crush = false) {
        this.socket.emit('destroyIceCube', {
            id: this.manager.myPenguinId,
            secret: this.manager.myPenguinSecret,
            cubeId: cubeId,
            crush: !!crush
        });
    }

    emitCrackIceCube(cubeId) {
        this.socket.emit('crackIceCube', {
            id: this.manager.myPenguinId,
            secret: this.manager.myPenguinSecret,
            cubeId: cubeId
        });
    }

}

