}

setupResizeHandler() {
    window.addEventListener('resize', () => {
        if (window.calculateIglooPos) {
            const pos = window.calculateIglooPos();
            this.startX = pos.x;
            this.startY = pos.y;
        }
    });
}

initIdentity() {
    let savedId = localStorage.getItem('penguinId');
    let savedName = localStorage.getItem('penguinName');
    let savedSecret = localStorage.getItem('penguinSecret');

    if (!savedId) {
        savedId = Math.random().toString(36).substring(2, 15);
        // We no longer pick a local name here, the server will assign one if needed
        savedName = "Pengu"; // Temporary placeholder
        localStorage.setItem('penguinId', savedId);
        localStorage.setItem('penguinName', savedName);
    }

    if (!savedSecret) {
        savedSecret = Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
        localStorage.setItem('penguinSecret', savedSecret);
    }

    this.myPenguinId = savedId;
    this.myPenguinName = savedName;
    this.myPenguinSecret = savedSecret;
}

/**
 * Admin gate for console-only debug commands (see window.teleportTo /
 * window.listWorlds in js/penguins.js). Add your penguinId to
 * GameConfig.ADMIN_PENGUIN_IDS to unlock these locally; this is a soft
 * client-side convenience gate, not real auth (see .clinerules SECURITY).
 */
isAdmin() {
    return GameConfig.ADMIN_PENGUIN_IDS.includes(this.myPenguinId);
}

setupKeyboard() {
    window.addEventListener('keydown', (e) => {
        const k = e.key.toLowerCase();

        // Map Space to W (Jump) and prevent scrolling if in-game
        if (e.key === ' ') {
            const player = this.penguins.find(p => p.isPlayer);
            // Only hijack space if player is spawned and NOT in igloo transition
            if (player && !player.isEntering && !player.isLeaving) {
                e.preventDefault();

                // If near an ice hole, trigger salvage instead of jump
                if (this.salvage && (this.salvage.activeHole || this.salvage.state !== 'idle')) {
                    this.salvage.handleInput(player);
                } else {
                    this.keys.w = true;
                }
            }
        }

        if (this.keys.hasOwnProperty(k)) this.keys[k] = true;

        // Speech Bubble Test - Infinite duration as requested
        if (k === 't') {
            const player = this.penguins.find(p => p.isPlayer);

