throwSnowball(player) {
    if (this.snowballCooldown > 0) return;
    if (player.state === 4) return; // Block throwing while sliding to prevent invulnerability exploits!

    this.snowballCooldown = 5.0; // 5-second long cooldown!

    const snowballId = player.id + "_" + Date.now();
    this.spawnSnowball(player.x, player.y - 4, player.direction, player.id, snowballId);
    this.network.emitThrowSnowball(player.x, player.y - 4, player.direction, player.id, snowballId);
}

isEnemyId(id) {
    return this.enemies.isEnemy(id);
}

spawnSnowball(x, y, direction, ownerId, snowballId, worldOverride, vy, gravity) {
    if (!this.snowballs) this.snowballs = [];
    const owner = this.penguins.find(p => p.id === ownerId) || this.remotePenguins[ownerId];
    const world = worldOverride || (owner ? (owner.currentWorld || owner.world || 'lobby') : 'lobby');
    const s = new Snowball(x, y, direction, ownerId, this, snowballId, vy, gravity);
    s.world = world;
    this.snowballs.push(s);
}

checkFishCollision(player) {
    if (this.goldenFish && player) {
        const playerWorld = player.currentWorld || 'lobby';
        if (this.goldenFishWorld !== playerWorld) return;

        const dx = player.x - this.fishX;
        const dy = player.y - this.fishY;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < GameConfig.FISH_COLLISION_RADIUS) {
            this.network.emitCatchFish(player.id, player.name);
        }
    }
}

checkPowerUpCollision(player) {
    if (this.powerUpFish && player) {
        const playerWorld = player.currentWorld || 'lobby';
        if (this.powerUpFish.world !== playerWorld) return;

        const dx = player.x - this.puX;
        const dy = player.y - this.puY;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < GameConfig.FISH_COLLISION_RADIUS) {
            player.applyPowerUp(this.currentPowerUpType);
            this.network.emitCatchPowerUp(player.id, this.currentPowerUpType);
            this.removePowerUpFish();
            this.effects.spawnStarExplosion(this.puX, this.puY);
        }
    }

    // Check test power-ups
    if (player && this.testPowerUps) {
        this.testPowerUps.forEach(pu => {
            const dx = player.x - (pu.x + 16);
            const dy = player.y - (pu.y + 16);
            const dist = Math.sqrt(dx * dx + dy * dy);
            if (dist < GameConfig.FISH_COLLISION_RADIUS) {
                player.applyPowerUp(pu.type);
                this.network.emitCatchPowerUp(player.id, pu.type);
                this.effects.spawnStarExplosion(pu.x + 16, pu.y + 16);
                pu.element.remove();
                // Let server signal others to remove it too
            }
        });
    }
}
