const categories = [
    { id: 'consumables', label: 'Items' },
    { id: 'clothing', label: 'Clothes' },
    { id: 'customization', label: 'Custom' }
];

categories.forEach((cat, index) => {
    const tab = document.createElement('div');
    tab.className = `shop-tab ${index === 0 ? 'active' : ''}`;
    tab.dataset.target = cat.id;
    tab.textContent = cat.label;
    tab.onclick = () => this.switchShopTab(cat.id);
    tabBar.appendChild(tab);
});
this.shopWindow.appendChild(tabBar);

// Content Panels
this.shopPanels = {};
categories.forEach((cat, index) => {
    const panel = document.createElement('div');
    panel.className = `shop-panel ${index === 0 ? 'active' : ''}`;
    panel.id = `shop-panel-${cat.id}`;

    const items = GameConfig.SHOP_ITEMS[cat.id] || [];
    items.forEach(item => {
        const itemEl = document.createElement('div');
        itemEl.className = 'shop-item';
        itemEl.innerHTML = `
            <div class="shop-item-info">
                <div class="shop-item-icon">${item.icon}</div>
                <div class="shop-item-details">
                    <div class="shop-item-name">${item.name}</div>
                    <div class="shop-item-price">${item.price} 🐟</div>
                </div>
            </div>
            <button class="buy-btn" data-id="${item.id}" data-price="${item.price}">BUY</button>
        `;

        itemEl.querySelector('.buy-btn').onclick = (e) => {
            this.manager.network.emitBuyItem(item.id);
        };

        panel.appendChild(itemEl);
    });

