    this.renderInventory();
}

handleDropRequest(slotIndex) {
    const inv = this.manager.inventory || [];
    if (!inv[slotIndex]) return;

    const player = this.manager.penguins.find(p => p.isPlayer);
    if (!player) return;

    this.manager.network.emitDropItem(slotIndex, player.id, this.manager.myPenguinSecret);
}

updateLeaderboard(sorted) {
    this.fullLeaderboard = sorted;
    this.renderHighscore();
}

updateTopCatcher(name, score) {
    this.topCatcherName = name;
    this.topCatcherScore = score;
    this.updateStatsDetails();
}

renderHighscore() {
    if (!this.highscoreContainer) return;

    const myId = this.manager.myPenguinId;
    // Search for my entry either by id OR by name if id is missing in leaderboard entries
    const myRankIndex = this.fullLeaderboard.findIndex(p => p.id === myId || (p.name === this.manager.myPenguinName && !p.id));

    let html = '';
    const medals = { 1: '🥇', 2: '🥈', 3: '🥉' };

    this.fullLeaderboard.forEach((p, index) => {
        // Match against current player
        const isMe = p.id === myId || (p.name === this.manager.myPenguinName && !p.id);
        const rank = index + 1;
        const medal = medals[rank] ? `<span class="medal">${medals[rank]}</span>` : `#${rank}`;

        html += `
            <div class="highscore-item ${isMe ? 'me' : ''}" id="rank-item-${rank}">
                <span class="highscore-rank">${medal}</span>
                <span class="highscore-name" style="${isMe ? 'font-weight: 800;' : ''}">${p.name}</span>
                <span class="highscore-score">${p.score}</span>
            </div>
        `;
    });

    if (this.fullLeaderboard.length === 0) {
        html = '<div style="text-align:center; padding: 10px; color: #888;">No scores yet today</div>';
    }

    this.highscoreContainer.innerHTML = html;

