    _installed: false,
    _manager: null,
    _watcher: null,
    _lockedRefs: new Map(), // name -> secured function reference
    _flagCooldowns: new Map(), // reason -> last flag timestamp

    /**
     * Install all guards. Call once, after `window.penguinManager` exists.
     */
    install(manager) {
        if (this._installed) return;
