draw() {
    // Swap background image dynamically depending on glasses state
    const targetSpriteSheet = this.activeGlasses ? '/img/Penguin SpriteSheet_Glasses.png' : GameConfig.SPRITE_SHEET_PATH;
    if (this.currentSpriteSheet !== targetSpriteSheet) {
        this.currentSpriteSheet = targetSpriteSheet;
        this.element.style.backgroundImage = `url("${targetSpriteSheet}")`;
        this.element.style.setProperty('--sprite-mask', `url("${targetSpriteSheet}")`);
    }

    this.element.style.left = (this.x - 16) + 'px';

    // Adjust Y to keep feet on the floor when scaling
    let drawScaleY = this.scale;
    if (this.pancakeTimer > 0) {
        drawScaleY *= 0.2;
    }

    this.element.style.top = (this.y - 16) + 'px';

    // Add a tiny vertical offset (0.5px) to prevent "bleeding" of the row above
    // during animations, which can cause a flickering line at the top.
    const yOffset = (this.state * 32) + 0.5;
    this.element.style.backgroundPosition = `-${this.frame * 32}px -${yOffset}px`;

    // Expose sprite coordinates for custom color masking/sheen sweeps
    this.element.style.setProperty('--sprite-pos-x', `-${this.frame * 32}px`);
    this.element.style.setProperty('--sprite-pos-y', `-${yOffset}px`);

    this.element.style.transform = `scale(${this.scale * this.direction}, ${drawScaleY})`;
    this.element.style.opacity = this.swimming ? this.opacity * GameConfig.WATER_OPACITY : this.opacity;

    // Pixelated rendering only for Giant penguins, smoother for normal ones
    if (this.powerUpType === 'giant') {
        this.element.style.imageRendering = 'pixelated';
    } else {
        this.element.style.imageRendering = 'auto';
    }

    const isGray = this.activeColor === 'color_gray';

