/**
 * SalvageManager.js
 * Handles the 100% vegan "Ice Magnet Salvage" mini-game state machine and timing.
 */
import { WORLDS } from './MapManager.js';
import { Effects } from './Effects.js';

export class SalvageManager {
    constructor(manager) {
        this.manager = manager;
        this.state = 'idle'; // 'idle', 'casting', 'waiting', 'bite', 'reeling'
        this.timer = 0;
        this.biteWindow = 0.7; // 700ms reaction window
        this.activeHole = null;
        this.ropeElement = null;
        this.magnetElement = null;
    }

    update(dt, player) {
        if (!player) return;

        if (this.state === 'idle') {
            this.checkProximity(player);
        } else {
            this.timer -= dt;

            if (this.state === 'casting') {
                if (this.timer <= 0) {
                    this.state = 'waiting';
                    this.timer = 2 + Math.random() * 3;
                }
            } else if (this.state === 'waiting') {
                if (this.timer <= 0) {
                    this.triggerBite(player);
                }
            } else if (this.state === 'bite') {
                if (this.timer <= 0) {
                    this.fail(player);
                }
            }

            player.vx = 0;
            player.state = 0;
            this.updateRope(player);
        }
    }

    checkProximity(player) {
        const world = WORLDS[player.currentWorld || 'lobby'];
        if (!world || !world.iceHole) {
            this.activeHole = null;
            return;
        }

        const hole = world.iceHole;
        if (player.x >= hole.x1 && player.x <= hole.x2) {
            this.activeHole = hole;
            if (!player.speechBubble && !this.manager.isPassive) {
                const hasMagnet = this.manager.inventory.some(item => item && item.type === 'magnet');
                if (!hasMagnet) {
                    this.manager.effects.showSpeechBubble(player, "I need a Magnet from the Shop! 🧲", 1.0);
                } else {
                    const isSelected = this.manager.ui.selectedIndex !== -1 && 
                                       this.manager.inventory[this.manager.ui.selectedIndex]?.type === 'magnet';
                    if (!isSelected) {
                        this.manager.effects.showSpeechBubble(player, "Select your Magnet! 🎒", 1.0);
                    } else {
                        this.manager.effects.showSpeechBubble(player, "Press SPACE to start Salvage! 🧲", 1.0);
                    }
                }
            }
        } else {
            this.activeHole = null;
        }
    }

    handleInput(player) {
        if (this.state === 'idle') {
            if (this.activeHole) {
                const selectedItem = this.manager.inventory[this.manager.ui.selectedIndex];
                if (selectedItem && selectedItem.type === 'magnet') {
                    this.startSalvage(player);
                }
            }
        } else if (this.state === 'bite') {
            this.success(player);
        }
    }

    startSalvage(player) {
        this.state = 'casting';
        this.timer = 1.0;
        this.manager.effects.showSpeechBubble(player, "Lowering Magnet... 🧲");
        player.direction = (player.x < (this.activeHole.x1 + this.activeHole.x2)/2) ? 1 : -1;
        this.createVisuals(player);
    }

    triggerBite(player) {
        this.state = 'bite';
        this.timer = this.biteWindow;
        this.manager.effects.showSpeechBubble(player, "❗ CLANK! ❗", this.biteWindow);
        Effects.popEmote(player.x, player.y - 20, '!', 10);
    }

    success(player) {
        this.state = 'reeling';
        this.timer = 1.0;
        this.manager.effects.showSpeechBubble(player, "Reeling in Treasure! ✨");

        const r = Math.random();
        let reward = { type: 'fish', icon: '🐟', qty: 5, msg: "Found some old Fish! +5 🐟" };
        if (r < 0.1) reward = { type: 'golden_fish', icon: '🐠', qty: 1, msg: "RESCUED A BUBBLE FISH! +1 🐠✨" };
        else if (r < 0.3) reward = { type: 'coin', icon: '🪙', qty: 15, msg: "Found Ancient Coins! +15 🐟" };
        else if (r < 0.5) reward = { type: 'gem', icon: '💎', qty: 25, msg: "Glacier Gem found! +25 🐟" };

        setTimeout(() => {
            if (this.manager.effects.spawnStarExplosion) this.manager.effects.spawnStarExplosion(player.x, player.y);
            this.manager.effects.showSpeechBubble(player, reward.msg, 3.0);
            Effects.popEmote(player.x, player.y, reward.icon, 20);
            this.manager.network.socket.emit('claimSalvage', { 
                id: player.id, 
                secret: this.manager.myPenguinSecret,
                rewardType: reward.type 
            });
            this.cleanup();
        }, 1000);
    }

    fail(player) {
        this.state = 'idle';
        this.manager.effects.showSpeechBubble(player, "It slipped away... 💨");
        this.cleanup();
    }

    createVisuals(player) {
        const header = document.querySelector('#header .inner-header') || document.getElementById('header');
        this.ropeElement = document.createElement('div');
        this.ropeElement.style.position = 'absolute';
        this.ropeElement.style.width = '2px';
        this.ropeElement.style.background = '#ddd';
        this.ropeElement.style.zIndex = '8990';
        header.appendChild(this.ropeElement);
        this.magnetElement = document.createElement('div');
        this.magnetElement.style.position = 'absolute';
        this.magnetElement.style.fontSize = '16px';
        this.magnetElement.textContent = '🧲';
        this.magnetElement.style.zIndex = '8991';
        header.appendChild(this.magnetElement);
    }

    updateRope(player) {
        if (!this.ropeElement || !this.magnetElement) return;
        const startX = player.x + (player.direction * 15);
        const startY = player.y + 10;
        const holeCenterX = (this.activeHole.x1 + this.activeHole.x2) / 2;
        const targetX = holeCenterX;
        const targetY = player.y + 40;
        let currentY = startY;
        if (this.state === 'casting') currentY = startY + (targetY - startY) * (1 - this.timer);
        else if (this.state === 'waiting' || this.state === 'bite') currentY = targetY + Math.sin(Date.now() / 200) * 3;
        else if (this.state === 'reeling') currentY = targetY - (targetY - startY) * (1 - this.timer);
        const dx = targetX - startX;
        const dy = currentY - startY;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const angle = Math.atan2(dy, dx);
        this.ropeElement.style.height = dist + 'px';
        this.ropeElement.style.left = startX + 'px';
        this.ropeElement.style.top = startY + 'px';
        this.ropeElement.style.transform = `rotate(${angle - Math.PI/2}rad)`;
        this.ropeElement.style.transformOrigin = 'top center';
        this.magnetElement.style.left = (targetX - 8) + 'px';
        this.magnetElement.style.top = (currentY - 8) + 'px';
    }

    cleanup() {
        if (this.ropeElement) this.ropeElement.remove();
        if (this.magnetElement) this.magnetElement.remove();
        this.ropeElement = null;
        this.magnetElement = null;
        this.state = 'idle';
        this.timer = 0;
    }
}

