checkChallengeFishCollision(player) {
    if (this.hasChallengeFish && player && player.currentWorld === 'caves') {
        const dx = player.x - this.challengeFishX;
        const dy = player.y - this.challengeFishY;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < 32) {
            this.hasChallengeFish = false;
            const el = document.getElementById('challenge-golden-fish');
            if (el) el.remove();

            this.effects.spawnStarExplosion(player.x, player.y);
            this.effects.showSpeechBubble(player, "CHALLENGE COMPLETED! +1 🐠✨", 3.0);

            this.network.socket.emit('claimChallengeFish', {
                id: player.id,
                secret: this.myPenguinSecret
            });

            // Teleport back in victory!
            setTimeout(() => {
                MapManager.transitionWorld(this, player, 'lobby', 1000);
            }, 1500);
        }
    }
}

